def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def composite_numbers():
    return [n for n in range(1, 101) if not is_prime(n)]

def find_max_product_sum(k, target):
    composites = composite_numbers()
    from itertools import combinations
    best_combination = None
    max_product = -float('inf')
    for r in range(2, len(composites) + 1):
        for combination in combinations(composites, r):
            if sum(combination) == target:
                product = 1
                for num in combination:
                    product *= num
                if product > max_product:
                    max_product = product
                    best_combination = combination
    return best_combination

