def find_parens(s):
    stack = []
    max_length = 0
    start_index = 0
    end_index = 0

    for i in range(len(s)):
        if s[i] == '(':
            stack.append(i)
        else:
            if stack:
                start = stack.pop()
                if not stack or (i - start > max_length):
                    max_length = i - start
                    start_index = start
                    end_index = i + 1

    return start_index, end_index

