def combinationsSum(k, n):
  # Check for invalid input values of k and n
  if type(k) != int or type(n) != int: raise TypeError("Both k and n need to be integers")
  if k < 0 or n < 0: raise ValueError("Both k and n need to be non-negative integers")

  # Recursive helper function to find all combinations that add up to target. The path list.
  def backtrack(curr_comb, remaining, start, remaining_sum):
    # If the remaining sum is 0 check if the current combination's length is equal to target
    # If so add curr_comb to result,
    # otherwise no need to backtrack and the curr_comb doesn't qualify
    if remaining_sum == 0 and len(curr_comb) == k:
      result.append(curr_comb[:])

      # Move on to the next combo
    elif remaining_sum > 0 and len(curr_comb) < k:
      for num in range(start, 9 + 1):
        curr_comb.append(num)
        backtrack(curr_comb, 1 + num, num + 1, remaining_sum - num)
        curr_comb.pop()
    elif remaining_sum > 0:
      for num in range(start, int(remaining_sum / k + 1)):
        curr_comb.append(num)
        backtrack(curr_comb, num, num + 1, remaining_sum - num)
        curr_comb.pop()

  # Initialize result list
  result = []

  # Backtrack with an empty combination list
  backtrack([], 0, 1, n)

  # Return list of lists representing all combinations that meet the criteria
  return result

