        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left+1:right]

    result = ""
    for i in range(len(s)):
        sub = expand(s, i, i)
        if len(sub) > len(result):
            result = sub
        sub = expand(s, i, i+1)
        if len(sub) > len(result):
            result = sub
    return result

def solve(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    max_len = 0
    start = 0

    for i in range(n-1, -1, -1):
        for j in range(i, n):
            if i == j or s[i] == s[j]:
                if i + 1 <= j - 1:
                    dp[i][j] = dp[i+1][j-1]
                else:
                    dp[i][j] = True
                if dp[i][j]:
                    length = j - i + 1
                    if length > max_len:
                        max_len = length
                        start = i
    return s[start:start+max_len]

