from collections import Counter

def solve(nums, k):
    count = Counter(nums)
    most_common = count.most_common()
    max_freq = most_common[0][1]
    candidates = []
    for num, freq in most_common:
        if freq == max_freq:
            candidates.append(num)
        else:
            break
    return candidates[:k]

